/// Round to nearest, half away from zero (gpsctl's scaleRound()).  Plain truncation would turn
/// 1.15 * 100.0 (= 114.99999999999999) into 114.
/// Wide enough for the largest field (fixed altitude variance, a U4 scaled by 10000).
pub fn scale_round(value: f64, scale: f64) -> i64 {
    let v = value * scale;
    (if v < 0.0 { v - 0.5 } else { v + 0.5 }) as i64
}

/// UBX 8-bit Fletcher checksum over class, id, length and body.
pub fn fletcher(bytes: &[u8]) -> (u8, u8) {
    let (mut a, mut b) = (0u8, 0u8);
    for &x in bytes {
        a = a.wrapping_add(x);
        b = b.wrapping_add(a);
    }
    (a, b)
}

#[derive(Debug, Clone, PartialEq)]
pub struct Nav5 {
    pub dyn_model: u8,
    pub fix_mode: u8,
    pub fixed_alt_m: f64,
    pub fixed_alt_var_m2: f64,
    pub min_elev: u8,
    pub pdop: f64,
    pub tdop: f64,
    pub pacc: u16,
    pub tacc: u16,
    pub static_hold_thresh: u8,
    pub dgnss_timeout: u8,
    pub cno_thresh_num_svs: u8,
    pub cno_thresh: u8,
    pub static_hold_max_dist: u16,
    pub utc_standard: u8,
}

impl Nav5 {
    /// The 36-byte CFG-NAV5 body.
    pub fn body(&self) -> [u8; 36] {
        let mut b = [0u8; 36];
        b[0..2].copy_from_slice(&0x05F7u16.to_le_bytes()); // mask: everything
        b[2] = self.dyn_model;
        b[3] = self.fix_mode;
        b[4..8].copy_from_slice(&(scale_round(self.fixed_alt_m, 100.0) as u32).to_le_bytes());
        b[8..12].copy_from_slice(&(scale_round(self.fixed_alt_var_m2, 10000.0) as u32).to_le_bytes());
        b[12] = self.min_elev;
        b[14..16].copy_from_slice(&(scale_round(self.pdop, 10.0) as u16).to_le_bytes());
        b[16..18].copy_from_slice(&(scale_round(self.tdop, 10.0) as u16).to_le_bytes());
        b[18..20].copy_from_slice(&self.pacc.to_le_bytes());
        b[20..22].copy_from_slice(&self.tacc.to_le_bytes());
        b[22] = self.static_hold_thresh;
        b[23] = self.dgnss_timeout;
        b[24] = self.cno_thresh_num_svs;
        b[25] = self.cno_thresh;
        b[28..30].copy_from_slice(&self.static_hold_max_dist.to_le_bytes());
        b[30] = self.utc_standard;
        b
    }

    /// The complete frame: B5 62 06 24 24 00 <body> CK_A CK_B.
    pub fn frame(&self) -> Vec<u8> {
        let mut f = vec![0xB5, 0x62, 0x06, 0x24, 36, 0];
        f.extend_from_slice(&self.body());
        let (a, b) = fletcher(&f[2..]);
        f.push(a);
        f.push(b);
        f
    }
}

/// One line of golden.txt: parameters, then ':' and the expected frame bytes in hex.
pub fn parse_golden_line(line: &str) -> (String, Nav5, Vec<u8>) {
    let (left, right) = line.split_once(" : ").expect("golden line has ' : '");
    let t: Vec<&str> = left.split_whitespace().collect();
    let p = |i: usize| t[i].parse::<f64>().unwrap();
    let n = Nav5 {
        dyn_model: p(1) as u8,
        fix_mode: p(2) as u8,
        fixed_alt_m: p(3),
        fixed_alt_var_m2: p(4),
        min_elev: p(5) as u8,
        pdop: p(6),
        tdop: p(7),
        pacc: p(8) as u16,
        tacc: p(9) as u16,
        static_hold_thresh: p(10) as u8,
        dgnss_timeout: p(11) as u8,
        cno_thresh_num_svs: p(12) as u8,
        cno_thresh: p(13) as u8,
        static_hold_max_dist: p(14) as u16,
        utc_standard: p(15) as u8,
    };
    let bytes = right.split_whitespace().map(|h| u8::from_str_radix(h, 16).unwrap()).collect();
    (t[0].to_string(), n, bytes)
}

#[cfg(test)]
mod tests {
    use super::*;

    const GOLDEN: &str = include_str!("../c-golden/golden.txt");

    #[test]
    fn frames_match_the_c_implementation() {
        let mut n = 0;
        for line in GOLDEN.lines().filter(|l| !l.trim().is_empty()) {
            let (name, params, expected) = parse_golden_line(line);
            assert_eq!(params.frame(), expected, "case {name}");
            n += 1;
        }
        assert!(n >= 6);
    }

    #[test]
    fn rounding_not_truncation() {
        assert_eq!(scale_round(1.15, 100.0), 115); // truncation gives 114
        assert_eq!(scale_round(-1.15, 100.0), -115);
        assert_eq!(scale_round(2.3, 10.0), 23);
        assert_eq!(scale_round(-0.005, 100.0), -1); // half away from zero
    }

    #[test]
    fn fletcher_known_value() {
        // UBX-CFG-RATE poll: B5 62 06 08 00 00 -> checksum 0E 30
        assert_eq!(fletcher(&[0x06, 0x08, 0x00, 0x00]), (0x0E, 0x30));
    }
}
